{"expected_revision_id": "e37c04f1-e3dd-4eab-9aa9-7b24f78ba5ea", "source": "module rising_edge(input clk, rst, din, output reg pulse);
reg previous;
always @(posedge clk) begin
    if (rst) begin
        previous <= 1'b0;
        pulse    <= 1'b0;
    end else begin
        pulse    <= din & ~previous;
        previous <= din;
    end
end
endmodule
"}
